import{_ as n,l as s,o as e,c as i,v as t,p as l,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"SSA 构造 Cytron","description":"","frontmatter":{"title":"SSA 构造 Cytron","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssa-construction-cytron.md","filePath":"cs/ssa-construction-cytron.md","lastUpdated":1789023840000}'),S={name:"cs/ssa-construction-cytron.md"};function h(u,a,m,A,_,C){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="ssa-构造-cytron" tabindex="-1">SSA 构造 Cytron <a class="header-anchor" href="#ssa-构造-cytron" aria-label="Permalink to &quot;SSA 构造 Cytron&quot;">​</a></h1><div class="epigraph"><p>在支配边界插入 φ，再按支配树重命名，得到静态单赋值。Cytron 等人给出与支配树相关的高效放置。</p><footer>—— 据 Cytron et al., Efficiently Computing Static Single Assignment Form, 1991；Lengauer and Tarjan 支配；Appel, SSA is Functional Programming 整理</footer></div><p>上一课<a href="/cs/value-range-analysis">值范围</a>已在 SSA 上说话。主干<a href="/cs/ssa-form">SSA</a>给直觉。缺口是<strong>构造算法</strong>：支配树、支配边界、φ 迭代插入、重命名栈。本课钉 Cytron 步骤，不写析构——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素在每个汇合点对每个变量插 φ 太多。只需：变量在块定值，则在其支配边界插 φ，再迭代。缺口是<strong>支配边界 DF</strong>，不是值编号。</p><p>Lengauer–Tarjan 算支配。剪枝 SSA：无 use 的名不插 φ。semi-pruned 用 liveness 粗筛。</p><h3 id="φ-的操作数对应前驱边" tabindex="-1">φ 的操作数对应前驱边 <a class="header-anchor" href="#φ-的操作数对应前驱边" aria-label="Permalink to &quot;φ 的操作数对应前驱边&quot;">​</a></h3><p>顺序与 CFG 前驱列表对齐。错位则语义错。这不是「任意交换」。</p><p><span class="marginnote">Cytron et al. 1991 TOPLAS。Appel 1998。主干 SSA 课已禁止把 φ 当机器指令。本课补算法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ol><li>算支配树与 DF。2. 对每个变量的定值块工作表插 φ。3. 支配树 DFS，栈重命名，φ 操作数填入到达名。</li></ol>',11)),(e(),l(d,null,{default:r(()=>[p(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20DOM%5B%22%E6%94%AF%E9%85%8D%E6%A0%91%22%5D%0A%20%20DOM%20--%3E%20DF%5B%22%E6%94%AF%E9%85%8D%E8%BE%B9%E7%95%8C%22%5D%0A%20%20DF%20--%3E%20PHI%5B%22%E6%8F%92%20%CF%86%22%5D%0A%20%20PHI%20--%3E%20RN%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 mem2reg：alloca 的 store/load 先当定值/使用再走同一算法——接 SROA。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不可约 CFG 仍可 SSA，φ 更多。关键边有时先拆，方便后边析构。不要在构造时做 GVN；顺序是先 SSA 再优化。</p><p>复杂度：近线性支配 + 与定值数相关的 φ 插入。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 memory SSA 的全部 chi/mu。后课默认：标量可按 Cytron 构造 SSA。下一课析构：离开 SSA，φ 变传送。</p><p>也不把 SSA 当源语言语法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Cytron：DF 上插 φ，支配序重命名。</li><li>剪枝减少无用 φ。</li><li>支配算法用 Lengauer–Tarjan 等。</li><li>出处：Cytron et al., 1991；Lengauer–Tarjan；Appel, 1998。</li></ul>',9))])}const g=n(S,[["render",h]]);export{D as __pageData,g as default};
